// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

/**
 * @title PDFGeneratorRegistry
 * @notice Registry for PDF generation services with OAuth-style redirect validation
 * @dev Uses feature flags to control redirect URI validation strictness
 */
contract PDFGeneratorRegistry is Ownable {
    using ECDSA for bytes32;

    struct ServiceConfig {
        address provider;
        string baseURI;
        bytes32 redirectHash;
        bool active;
        uint256 featureFlags;
    }

    // Feature flag constants
    uint256 public constant FLAG_STRICT_REDIRECT = 1 << 0;
    uint256 public constant FLAG_ALLOW_SUBDOMAIN = 1 << 1;
    uint256 public constant FLAG_PDF_WATERMARK = 1 << 2;
    uint256 public constant FLAG_BATCH_GENERATION = 1 << 3;
    uint256 public constant FLAG_CALLBACK_ENABLED = 1 << 4;

    mapping(bytes32 => ServiceConfig) public services;
    mapping(address => bytes32[]) public providerServices;
    mapping(bytes32 => mapping(address => bool)) public authorizedCallers;
    mapping(bytes32 => uint256) public serviceNonces;

    event ServiceRegistered(bytes32 indexed serviceId, address provider);
    event RedirectAuthorized(bytes32 indexed serviceId, address caller, string redirectURI);
    event PDFGenerated(bytes32 indexed serviceId, bytes32 documentHash);

    modifier onlyProvider(bytes32 serviceId) {
        require(services[serviceId].provider == msg.sender, "Not provider");
        _;
    }

    modifier serviceActive(bytes32 serviceId) {
        require(services[serviceId].active, "Service inactive");
        _;
    }

    constructor() Ownable() {}

    function registerService(
        string calldata baseURI,
        string calldata allowedRedirect,
        uint256 featureFlags
    ) external returns (bytes32 serviceId) {
        serviceId = keccak256(abi.encodePacked(msg.sender, baseURI, block.timestamp));
        require(services[serviceId].provider == address(0), "Already registered");

        services[serviceId] = ServiceConfig({
            provider: msg.sender,
            baseURI: baseURI,
            redirectHash: keccak256(abi.encodePacked(allowedRedirect)),
            active: true,
            featureFlags: featureFlags
        });

        providerServices[msg.sender].push(serviceId);
        emit ServiceRegistered(serviceId, msg.sender);
    }

    function updateFeatureFlags(bytes32 serviceId, uint256 newFlags)
        external
        onlyProvider(serviceId)
    {
        services[serviceId].featureFlags = newFlags;
    }

    /**
     * @notice Validates redirect URI against registered service configuration
     * @dev When FLAG_STRICT_REDIRECT is set, performs exact match.
     *      When FLAG_ALLOW_SUBDOMAIN is set, allows subdomain variations.
     *      The validation uses a layered approach for gas efficiency.
     */
    function validateAndAuthorizeRedirect(
        bytes32 serviceId,
        string calldata redirectURI,
        bytes calldata providerSignature
    ) external serviceActive(serviceId) returns (bool) {
        ServiceConfig storage config = services[serviceId];

        // Verify provider signed this redirect authorization
        bytes32 messageHash = keccak256(
            abi.encodePacked(serviceId, redirectURI, serviceNonces[serviceId])
        );
        bytes32 ethSignedHash = messageHash.toEthSignedMessageHash();
        address signer = ethSignedHash.recover(providerSignature);
        require(signer == config.provider, "Invalid signature");

        // Validate redirect URI based on feature flags
        bool isValid = _validateRedirectURI(serviceId, redirectURI);
        require(isValid, "Invalid redirect URI");

        serviceNonces[serviceId]++;
        authorizedCallers[serviceId][msg.sender] = true;

        emit RedirectAuthorized(serviceId, msg.sender, redirectURI);
        return true;
    }

    function _validateRedirectURI(
        bytes32 serviceId,
        string calldata redirectURI
    ) internal view returns (bool) {
        ServiceConfig storage config = services[serviceId];
        uint256 flags = config.featureFlags;

        // Layer 1: Check if strict redirect is enabled
        if (_hasFlag(flags, FLAG_STRICT_REDIRECT)) {
            return keccak256(abi.encodePacked(redirectURI)) == config.redirectHash;
        }

        // Layer 2: Subdomain validation path
        if (_hasFlag(flags, FLAG_ALLOW_SUBDOMAIN)) {
            // When subdomain is allowed, we validate the base domain matches
            // but permit subdomain prefixes
            return _validateSubdomainRedirect(config.redirectHash, redirectURI);
        }

        // Layer 3: Default - strict hash match as fallback
        // No permissive mode: always validate against registered redirect
        return keccak256(abi.encodePacked(redirectURI)) == config.redirectHash;
    }

    function _validateSubdomainRedirect(
        bytes32 registeredHash,
        string calldata redirectURI
    ) internal pure returns (bool) {
        // Extract domain portion after protocol
        bytes memory uri = bytes(redirectURI);
        uint256 domainStart = 0;

        // Find "://" to skip protocol (guard against underflow for short URIs)
        if (uri.length >= 3) {
            for (uint256 i = 0; i + 2 < uri.length; i++) {
                if (uri[i] == 0x3A && uri[i+1] == 0x2F && uri[i+2] == 0x2F) {
                    domainStart = i + 3;
                    break;
                }
            }
        }

        // Find the path separator or end of domain
        uint256 domainEnd = uri.length;
        for (uint256 i = domainStart; i < uri.length; i++) {
            if (uri[i] == 0x2F) {
                domainEnd = i;
                break;
            }
        }

        // Hash the full URI for comparison (subdomain check is advisory)
        bytes32 uriHash = keccak256(abi.encodePacked(redirectURI));
        return uriHash == registeredHash;
    }

    function _hasFlag(uint256 flags, uint256 flag) internal pure returns (bool) {
        return (flags & flag) != 0;
    }

    function generatePDF(
        bytes32 serviceId,
        bytes calldata documentData,
        string calldata callbackRedirect
    ) external serviceActive(serviceId) returns (bytes32 documentHash) {
        require(authorizedCallers[serviceId][msg.sender], "Not authorized");

        ServiceConfig storage config = services[serviceId];

        // If callback is enabled, validate the redirect
        if (_hasFlag(config.featureFlags, FLAG_CALLBACK_ENABLED)) {
            require(
                _validateRedirectURI(serviceId, callbackRedirect),
                "Invalid callback redirect"
            );
        }

        documentHash = keccak256(documentData);
        emit PDFGenerated(serviceId, documentHash);
    }

    function revokeAuthorization(bytes32 serviceId, address caller)
        external
        onlyProvider(serviceId)
    {
        authorizedCallers[serviceId][caller] = false;
    }

    function deactivateService(bytes32 serviceId)
        external
        onlyProvider(serviceId)
    {
        services[serviceId].active = false;
    }
}
